/**
 * Python exception model.
 *
 * The original script lets exceptions escape `main()`, so the observable
 * behaviour of a failure is a CPython traceback on stderr plus the PyInstaller
 * bootstrap footer and exit status 1. `PythonError` carries the pieces needed
 * to reproduce that shape: the exception class name, its message, and the
 * stack of frames that were unwound.
 */

/** One rendered traceback frame. `source`/`caret` are optional. */
export function pyFrame(file, line, name, source = null, caret = null) {
  return { file, line, name, source, caret };
}

/** Caret annotation for a frame, as column offset + width within `source`. */
export function pyCaret(offset, length) {
  return { offset, length };
}

export class PythonError extends Error {
  constructor(pyType, pyMessage, frames = []) {
    super(`${pyType}: ${pyMessage}`);
    this.name = 'PythonError';
    this.pyType = pyType;
    this.pyMessage = pyMessage;
    this.frames = frames;
  }
}

export function raisePython(pyType, pyMessage, frames = []) {
  throw new PythonError(pyType, pyMessage, frames);
}

/**
 * Record that `frame` was on the stack when `err` propagated. Frames are
 * stored outermost-first, matching "most recent call last" ordering, so a
 * caller unwinding an exception prepends itself.
 */
export function prependFrame(err, frame) {
  if (err instanceof PythonError) {
    err.frames = [frame, ...err.frames];
  }
  return err;
}

/** Run `body`, tagging any Python exception with the calling frame. */
export function withFrame(frame, body) {
  try {
    return body();
  } catch (err) {
    throw prependFrame(err, frame);
  }
}

export function formatTraceback(err) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of err.frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
    if (frame.source !== null) {
      lines.push(`    ${frame.source}`);
      if (frame.caret !== null) {
        const pad = ' '.repeat(4 + frame.caret.offset);
        lines.push(`${pad}${'^'.repeat(frame.caret.length)}`);
      }
    }
  }
  lines.push(`${err.pyType}: ${err.pyMessage}`);
  return lines.join('\n');
}

