/**
 * Python `repr()` / `print()` formatting.
 *
 * Only the shapes the script actually emits are covered: lists of ints, bare
 * ints, and strings (the latter for `ValueError` messages).
 */

const SHORT_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

/** `repr()` of a str: single quotes unless that would need escaping. */
export function reprString(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";
  let body = '';
  for (const ch of value) {
    const escape = SHORT_ESCAPES.get(ch);
    if (escape !== undefined) {
      body += escape;
      continue;
    }
    if (ch === quote) {
      body += `\\${ch}`;
      continue;
    }
    const code = ch.codePointAt(0);
    if (code < 0x20 || code === 0x7f) {
      body += `\\x${code.toString(16).padStart(2, '0')}`;
      continue;
    }
    body += ch;
  }
  return `${quote}${body}${quote}`;
}

/** `repr()` of an int: never exponential notation, unlike JS `String()`. */
export function reprInt(value) {
  if (typeof value === 'bigint' || Number.isSafeInteger(value)) {
    return value.toString();
  }
  return Number.isFinite(value) ? BigInt(value).toString() : String(value);
}

export function reprList(items) {
  return `[${items.map(reprValue).join(', ')}]`;
}

export function reprValue(value) {
  if (Array.isArray(value)) return reprList(value);
  if (typeof value === 'string') return reprString(value);
  if (value === null || value === undefined) return 'None';
  return reprInt(value);
}

/** `print(value)`: str values pass through verbatim, everything else is repr'd. */
export function pyPrint(value) {
  console.log(typeof value === 'string' ? value : reprValue(value));
}

