/**
 * Python `int(str)` for base 10.
 *
 * Accepts surrounding whitespace, an optional sign, and PEP 515 underscores
 * between digits; anything else raises the same ValueError CPython does.
 */

import { PythonError } from './errors.mjs';
import { reprString } from './repr.mjs';

const DECIMAL_LITERAL = /^[+-]?\d+(?:_\d+)*$/;

export function pyInt(text, frames = []) {
  const stripped = text.trim();
  if (DECIMAL_LITERAL.test(stripped)) {
    return Number(stripped.replace(/_/g, ''));
  }
  throw new PythonError(
    'ValueError',
    `invalid literal for int() with base 10: ${reprString(text)}`,
    frames,
  );
}

/** `list(map(int, parts))` — reports the first offending element, like Python. */
export function pyIntList(parts, frames = []) {
  return parts.map((part) => pyInt(part, frames));
}

